// SQL (MySQL) equivalent:
// SELECT c1.id,
//        IFNULL(c1.drink,
//          (SELECT c2.drink FROM CoffeeShop c2
//           WHERE c2.id < c1.id AND c2.drink IS NOT NULL
//           ORDER BY c2.id DESC LIMIT 1)) AS drink
// FROM CoffeeShop c1
// ORDER BY c1.id;
var changeNullValues = function(coffeeshop) {
  let last = null;
  return [...coffeeshop].sort((a, b) => a.id - b.id).map(r => {
    if (r.drink != null) last = r.drink;
    else r.drink = last;
    return r;
  });
};

